_out += "</span>\n    </div>\n  </nav>\n\n  <div class=\"container\">\n    <h1 class=\"page-title\">🚫 Cancel WO</h1>\n    <p class=\"page-subtitle\">WO yang masih bisa dibatalkan: <b>belum dikerjakan</b>, <b>sedang dikerjakan</b>, <b>menunggu transfer</b>, atau <b>sudah dikirim mekanik tapi belum di-approve L1</b>. Setelah L1 approve, pembatalan hanya bisa oleh Supervisor atau Project Manager. Kalau WO salah buat, batalkan lalu buat WO baru yang benar.</p>\n    <div class=\"ringkas\" id=\"ringkas\"></div>\n    <input type=\"search\" class=\"cari\" id=\"cari\" placeholder=\"🔍 Cari nomor WO, komponen, unit, nama mekanik, pembuat…\" oninput=\"gambar()\">\n    <div id=\"daftar\"><div class=\"memuat\">⏳ Memuat daftar WO…</div></div>\n  </div>\n\n  <div class=\"modal\" id=\"modalCancel\">\n    <div class=\"modal-kotak\">\n      <h3 id=\"modalJudul\">Cancel WO</h3>\n      <p>WO ini akan <b>dibatalkan</b> dan tidak bisa dikembalikan. Mekanik tidak akan dibayar untuk WO ini. Tulis alasannya — tercatat di riwayat.</p>\n      <textarea id=\"alasan\" placeholder=\"Alasan pembatalan (wajib), mis. salah pilih komponen / kondisi kerja salah, akan dibuat ulang\"></textarea>\n      <div class=\"modal-galat\" id=\"modalGalat\"></div>\n      <div class=\"modal-tombol\">\n        <button class=\"btn-kembali\" onclick=\"tutupModal()\">Kembali</button>\n        <button class=\"btn-ya\" id=\"btnYa\" onclick=\"konfirmasi()\">🚫 Ya, Cancel WO</button>\n      </div>\n    </div>\n  </div>\n  <div class=\"toast\" id=\"toast\"></div>\n\n<script>\nvar DATA = [], SASARAN = null;\n\nfunction esc(s) {\n  return String(s === null || s === undefined ? '' : s).replace(/[&<>\"']/g, function (c) {\n    return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;'}[c];\n  });\n}\nfunction tgl(iso) {\n  if (!iso) return '';\n  var d = new Date(iso);\n  if (isNaN(d.getTime())) return '';\n  return d.toLocaleString('id-ID', {day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit'});\n}\nfunction toast(pesan) {\n  var t = document.getElementById('toast');\n  t.textContent = pesan; t.style.display = 'block';\n  clearTimeout(toast._t); toast._t = setTimeout(function () { t.style.display = 'none'; }, 4000);\n}\n\nfunction muat() {\n  google.script.run\n    .withSuccessHandler(function (res) {\n      if (!res || res.success === false) {\n        var m = (res && res.error && res.error.message) || 'Daftar gagal dimuat.';\n        document.getElementById('daftar').innerHTML = '<div class=\"galat\">' + esc(m) + '</div>';\n        return;\n      }\n      DATA = res.data || [];\n      gambar();\n    })\n    .withFailureHandler(function (err) {\n      document.getElementById('daftar').innerHTML =\n        '<div class=\"galat\">Daftar gagal dimuat — periksa sinyal lalu muat ulang halaman.<br><small>' + esc(err && err.message) + '</small></div>';\n    })\n    .handleDaftarCancelWo({token: PAGE_TOKEN});\n}\n\nfunction gambar() {\n  var q = String(document.getElementById('cari').value || '').toLowerCase().trim();\n  var hitung = {};\n  DATA.forEach(function (w) { hitung[w.status_label] = (hitung[w.status_label] || 0) + 1; });\n  var r = '<span><b>' + DATA.length + '</b> WO bisa dibatalkan</span>';\n  for (var k in hitung) if (hitung.hasOwnProperty(k)) r += '<span>' + esc(k) + ': <b>' + hitung[k] + '</b></span>';\n  document.getElementById('ringkas').innerHTML = r;\n\n  var tampil = DATA.filter(function (w) {\n    if (!q) return true;\n    return [w.wo_number, w.component_name, w.unit_name, (w.team_names || []).join(' '), w.created_by_name, w.status_label]\n      .join(' ').toLowerCase().indexOf(q) !== -1;\n  });\n  if (!DATA.length) { document.getElementById('daftar').innerHTML = '<div class=\"kosong\">Tidak ada WO yang bisa dibatalkan saat ini.</div>'; return; }\n  if (!tampil.length) { document.getElementById('daftar').innerHTML = '<div class=\"kosong\">Tidak ada yang cocok dengan pencarian.</div>'; return; }\n\n  document.getElementById('daftar').innerHTML = tampil.map(function (w) {\n    return '<div class=\"kartu\">' +\n      '<div class=\"kartu-atas\"><div class=\"no\">' + esc(w.wo_number) + '</div>' +\n        '<span class=\"lencana st-' + esc(w.status) + '\">' + esc(w.status_label) + '</span></div>' +\n      '<div class=\"isi\">' +\n        '<div>' + esc(w.component_name) + '</div>' +\n        '<div><span class=\"lbl\">Unit:</span> ' + esc(w.unit_name) + ' · ' + esc(w.location) + '</div>' +\n        '<div><span class=\"lbl\">Tim:</span> ' + esc((w.team_names || []).join(', ') || '-') + '</div>' +\n        '<div><span class=\"lbl\">Dibuat:</span> ' + esc(tgl(w.created_at)) + ' oleh ' + esc(w.created_by_name) + '</div>' +\n        (w.submitted_at ? '<div><span class=\"lbl\">Dikirim:</span> ' + esc(tgl(w.submitted_at)) + ' oleh ' + esc(w.submitted_by_name) + '</div>' : '') +\n      '</div>' +\n      '<button class=\"tombol-cancel\" data-id=\"' + esc(w.id) + '\">🚫 Cancel WO</button>' +\n    '</div>';\n  }).join('');\n}\n\nfunction bukaModal(id) {\n  SASARAN = null;\n  for (var i = 0; i < DATA.length; i++) if (String(DATA[i].id) === String(id)) SASARAN = DATA[i];\n  if (!SASARAN) return;\n  document.getElementById('modalJudul').textContent = 'Cancel ' + SASARAN.wo_number + '?';\n  document.getElementById('alasan').value = '';\n  document.getElementById('modalGalat').style.display = 'none';\n  var b = document.getElementById('btnYa'); b.disabled = false; b.textContent = '🚫 Ya, Cancel WO';\n  document.getElementById('modalCancel').className = 'modal tampil';\n  setTimeout(function () { document.getElementById('alasan').focus(); }, 50);\n}\nfunction tutupModal() { document.getElementById('modalCancel').className = 'modal'; SASARAN = null; }\n\n// Satu penangkap klik untuk semua tombol — id WO dibaca dari data-id, tak\n// pernah disisipkan ke dalam kode onclick.\ndocument.getElementById('daftar').addEventListener('click', function (e) {\n  var el = e.target;\n  while (el && el !== this && !(el.className && String(el.className).indexOf('tombol-cancel') !== -1)) el = el.parentNode;\n  if (el && el !== this) bukaModal(el.getAttribute('data-id'));\n});\n\nfunction konfirmasi() {\n  if (!SASARAN) return;\n  var alasan = String(document.getElementById('alasan').value || '').trim();\n  var g = document.getElementById('modalGalat');\n  if (!alasan) { g.textContent = 'Alasan wajib diisi.'; g.style.display = 'block'; return; }\n  var b = document.getElementById('btnYa'); b.disabled = true; b.textContent = '⏳ Membatalkan…';\n  var w = SASARAN;\n  google.script.run\n    .withSuccessHandler(function (res) {\n      if (!res || res.success === false) {\n        b.disabled = false; b.textContent = '🚫 Ya, Cancel WO';\n        g.textContent = (res && res.error && res.error.message) || 'Pembatalan ditolak.'; g.style.display = 'block';\n        return;\n      }\n      DATA = DATA.filter(function (x) { return String(x.id) !== String(w.id); });\n      tutupModal(); gambar();\n      toast('✅ ' + w.wo_number + ' dibatalkan');\n    })\n    .withFailureHandler(function (err) {\n      b.disabled = false; b.textContent = '🚫 Ya, Cancel WO';\n      g.textContent = 'Koneksi terputus — status pembatalan belum pasti. Muat ulang halaman dan periksa apakah WO-nya masih ada sebelum mencoba lagi.';\n      g.style.display = 'block';\n    })\n    .handleCancelWO({wo_id: w.id, reason: alasan, token: PAGE_TOKEN});\n}\n\nmuat();\n</script>\n</body>\n</html>\n";
