_out += "\n  </div>\n\n  <script>\n/**\n * PICKER TANGGAL & JAM 24 JAM — satu definisi untuk semua halaman web.\n * Sisipkan dengan include('DateTime24') di dalam <body>.\n *\n * KENAPA tidak memakai <input type=\"datetime-local\">:\n * format 12/24 jam pada picker bawaan ditentukan LOCALE PERANGKAT, bukan HTML.\n * Di ponsel yang locale-nya Inggris, picker memunculkan AM/PM — bentuk yang\n * tidak dipakai di lapangan sini, dan sumber salah isi yang mahal (jam 13.00\n * terbaca \"1\", lalu tersimpan jadi 01.00 → actual_hours meleset 12 jam, dan itu\n * jalur uang). Tidak ada atribut HTML/CSS untuk memaksanya, jadi bagian jamnya\n * dibuat sendiri: 00–23 dan 00–59, selalu 24 jam apa pun setelan ponselnya.\n * Bagian TANGGAL tetap <input type=\"date\"> — di sana tidak ada urusan AM/PM.\n *\n * BENTUK NILAI tidak berubah: hasilnya ditulis ke <input type=\"hidden\"> ber-ID\n * SAMA seperti dulu, dalam format \"YYYY-MM-DDTHH:MM\" (identik datetime-local).\n * Jadi seluruh kode yang MEMBACA `.value` tidak perlu diubah sama sekali.\n * Yang MENULIS wajib lewat dtSet(id, nilai) supaya kontrol di layar ikut pindah.\n */\n\n/** HTML satu kontrol. `id` = id input hidden yang dipakai kode lama. */\nfunction dtHtml(id, kelasInput) {\n  var k = kelasInput || 'form-input';\n  return '<input type=\"hidden\" id=\"' + id + '\">' +\n    '<div class=\"dt24\" data-dt=\"' + id + '\">' +\n      '<input type=\"date\" class=\"' + k + ' dtTgl\" aria-label=\"Tanggal\">' +\n      '<select class=\"' + k + ' dtJam\" aria-label=\"Jam\"></select>' +\n      '<span class=\"dtTitik\">:</span>' +\n      '<select class=\"' + k + ' dtMnt\" aria-label=\"Menit\"></select>' +\n    '</div>';\n}\n\nfunction _dt2(n) { return (n < 10 ? '0' : '') + n; }\n\n/** Isi opsi jam/menit & pasang pendengar. Aman dipanggil berulang. */\nfunction dtPasang(root) {\n  var grup = (root || document).querySelectorAll('.dt24');\n  for (var i = 0; i < grup.length; i++) {\n    var g = grup[i];\n    if (g.getAttribute('data-siap') === '1') continue;\n    g.setAttribute('data-siap', '1');\n\n    var oJam = '<option value=\"\">--</option>';\n    for (var h = 0; h < 24; h++) oJam += '<option value=\"' + _dt2(h) + '\">' + _dt2(h) + '</option>';\n    g.querySelector('.dtJam').innerHTML = oJam;\n\n    var oMnt = '<option value=\"\">--</option>';\n    for (var m = 0; m < 60; m++) oMnt += '<option value=\"' + _dt2(m) + '\">' + _dt2(m) + '</option>';\n    g.querySelector('.dtMnt').innerHTML = oMnt;\n\n    // 'change' untuk select, 'input' untuk <input type=\"date\"> — sebagian\n    // peramban Android baru mengirim 'change' setelah picker ditutup.\n    g.addEventListener('change', function() { dtKumpulkan(this); });\n    g.addEventListener('input',  function() { dtKumpulkan(this); });\n  }\n}\n\n/**\n * Trio di layar → input hidden. Lalu picu 'change' PADA input hidden supaya\n * handler lama (hitung durasi, penjaga override) tetap jalan seperti dulu.\n */\nfunction dtKumpulkan(g) {\n  var el = document.getElementById(g.getAttribute('data-dt'));\n  if (!el) return;\n  var t = g.querySelector('.dtTgl').value;\n  var j = g.querySelector('.dtJam').value;\n  var m = g.querySelector('.dtMnt').value;\n  // Belum lengkap = kosong. Separuh terisi tidak boleh jadi waktu tebakan —\n  // lebih baik validasi yang ada menolaknya daripada menyimpan jam ngawur.\n  var baru = (t && j !== '' && m !== '') ? (t + 'T' + j + ':' + m) : '';\n  if (el.value === baru) return;\n  el.value = baru;\n  el.dispatchEvent(new Event('change', {bubbles: true}));\n}\n\n/**\n * Satu-satunya cara sah menulis nilai picker.\n * @param {string} id  id input hidden\n * @param {string} s   \"YYYY-MM-DDTHH:MM\" (keluaran toDatetimeLocal) atau ''\n */\nfunction dtSet(id, s) {\n  var el = document.getElementById(id);\n  if (!el) return;\n  s = s ? String(s) : '';\n  if (s.length > 16) s = s.substring(0, 16);   // buang detik bila terbawa\n  el.value = s;\n  var g = document.querySelector('.dt24[data-dt=\"' + id + '\"]');\n  if (!g) return;\n  g.querySelector('.dtTgl').value = s ? s.substring(0, 10) : '';\n  g.querySelector('.dtJam').value = s ? s.substring(11, 13) : '';\n  g.querySelector('.dtMnt').value = s ? s.substring(14, 16) : '';\n}\n</script>\n\n<style>\n  /* Tanggal melebar, jam & menit sempit — dua kolom sempit berdampingan lebih\n     cepat dipindai daripada satu kolom lebar berisi angka gabungan. */\n  .dt24 { display: grid; grid-template-columns: minmax(0, 1fr) auto auto auto; gap: 6px; align-items: center; }\n  .dt24 .dtTgl { min-width: 0; }\n  .dt24 .dtJam, .dt24 .dtMnt { min-width: 0; width: auto; padding-left: 8px; padding-right: 4px;\n    font-variant-numeric: tabular-nums; text-align: center; }\n  .dt24 .dtTitik { font-weight: 700; opacity: 0.55; }\n  @media (max-width: 380px) { .dt24 { gap: 4px; } }\n</style>\n\n</body>\n</html>";
return _out;

