_out += _esc(getScriptUrl());
_out += "?page=create')};\n    }\n    function tombolCekLagi(teks) {\n      return {teks: teks || 'Cek status kiriman', gaya: 'primary',\n              aksi: function() { strukTutup(); kirimBlok(); }};\n    }\n\n    function labelUntuk(idx, srv) {\n      var l = (_labelTerakhir && _labelTerakhir[idx]) ? _labelTerakhir[idx] : '';\n      if (l) return l;                                    // nama sebagaimana terbaca di layar\n      var komp = (srv && srv.component_id) || '';         // sesudah muat ulang: tinggal kodenya\n      var unit = (srv && srv.unit_id) || '';\n      return (komp + (unit ? ' \\u00b7 ' + unit : '')) || '(tanpa keterangan)';\n    }\n\n    function strukDariHasil(d, kembar) {\n      var dibuat = d.created || [];\n      var gagal  = d.failed  || [];\n      var items = [], i;\n\n      for (i = 0; i < dibuat.length; i++) {\n        items.push({ok: true, no: dibuat[i].wo_number, sub: labelUntuk(dibuat[i].index, dibuat[i])});\n      }\n      for (i = 0; i < gagal.length; i++) {\n        items.push({\n          ok: false,\n          no: 'GAGAL \\u2014 blok #' + ((gagal[i].index || 0) + 1),\n          sub: labelUntuk(gagal[i].index, gagal[i]) + ' \\u2014 ' + (gagal[i].error || 'error tak diketahui')\n        });\n      }\n\n      var semua = d.total || items.length;\n      var o = {\n        judul: gagal.length ? ('\\u26a0\\ufe0f ' + dibuat.length + ' dari ' + semua + ' WO masuk')\n                            : ('\\u2705 ' + dibuat.length + ' WO berhasil dibuat'),\n        sub: gagal.length\n          ? 'Yang bernomor di bawah SUDAH tersimpan dan tidak perlu diulang.'\n          : 'Semua nomor di bawah sudah tersimpan di sistem.',\n        items: items,\n        tombol: [tombolBuatLagi()]\n      };\n\n      // \\u2500\\u2500\\u2500 SUKSES SEBAGIAN BUKAN GAGAL TOTAL \\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\\u2500\n      // createWorkOrdersBatch menjawab success=false bila SATU blok saja gagal.\n      // Dulu layar ini langsung berbunyi \"Gagal membuat WO\", jadi saat 5 dari 6\n      // berhasil pembuatnya wajar menyimpulkan semuanya gagal lalu mengulang\n      // keenam-enamnya \\u2014 dan lahirlah lima WO kembar.\n      if (gagal.length) {\n        o.note = 'Buat ulang HANYA blok yang bertanda \\u274c. Jangan ulangi semuanya \\u2014 ' +\n                 'yang sudah bernomor akan terbit dua kali.';\n        o.noteBuruk = true;\n      }\n      if (kembar) {\n        o.sub = 'Kiriman ini sudah pernah masuk sebelumnya. Tidak ada WO yang dibuat dua kali.';\n      }\n      return o;\n    }\n\n    function itemDariPulih(pulih) {\n      var items = [];\n      for (var i = 0; i < pulih.length; i++) {\n        items.push({\n          ok: true, no: pulih[i].wo_number,\n          sub: (pulih[i].component_id || '') + (pulih[i].unit_id ? ' \\u00b7 ' + pulih[i].unit_id : '')\n        });\n      }\n      return items;\n    }\n\n    function tanggapiKiriman(r) {\n      r = r || {};\n\n      if (r.kiriman === 'SEDANG' || r.kiriman === 'TAKPASTI') {\n        strukTampil({\n          judul: r.kiriman === 'SEDANG' ? '\\u23f3 Kiriman masih diproses' : '\\u23f3 Status belum bisa dipastikan',\n          sub: r.kiriman === 'SEDANG'\n            ? 'Kiriman yang sama sedang dikerjakan server. Ini bukan kegagalan.'\n            : 'Server sedang sibuk. Tidak ada WO yang dibuat pada percobaan ini.',\n          items: [],\n          note: 'Tunggu sekitar satu menit lalu tekan Cek status. JANGAN mengisi formulir baru \\u2014 ' +\n                'nomor kiriman inilah yang menjaga WO Anda tidak terbit dua kali.',\n          tombol: [tombolCekLagi()]\n        });\n        return;\n      }\n\n      if (r.kiriman === 'MACET') {\n        var pulih = r.pulih || [];\n        strukTampil(pulih.length ? {\n          judul: '\\u26a0\\ufe0f Kiriman terputus di tengah jalan',\n          sub: pulih.length + ' WO sempat masuk sebelum terputus:',\n          items: itemDariPulih(pulih),\n          note: 'Buat ulang HANYA pekerjaan yang TIDAK ada di daftar ini. Cocokkan dulu dengan ' +\n                'catatan Anda \\u2014 kalau ragu, tanyakan dulu sebelum mengulang.',\n          noteBuruk: true,\n          tombol: [tombolBuatLagi()]\n        } : {\n          judul: '\\u274c Kiriman sebelumnya terputus',\n          sub: 'TIDAK ADA WO yang masuk dari kiriman itu.',\n          items: [],\n          note: 'Aman dibuat ulang. Tekan Buat WO lagi lalu isi seperti semula.',\n          tombol: [tombolBuatLagi()]\n        });\n        hapusKirimanTertunda();\n        return;\n      }\n\n      var d = r.data || {};\n      if (d.created || d.failed) {\n        strukTampil(strukDariHasil(d, r.kiriman === 'SELESAI'));\n        hapusKirimanTertunda();\n        return;\n      }\n\n      // Jalur WO tunggal warisan (tanpa blocks). Halaman ini selalu mengirim\n      // blocks, jadi ini cuma jaring pengaman — tapi tanpanya WO yang JADI akan\n      // dilaporkan sebagai \"tidak dibuat\", dan itu jenis kebohongan yang persis\n      // memicu orang mengulang kiriman yang sudah berhasil.\n      if (d.wo_number) {\n        strukTampil({\n          judul: '✅ 1 WO berhasil dibuat',\n          sub: 'Nomor di bawah sudah tersimpan di sistem.',\n          items: [{ok: true, no: d.wo_number, sub: labelUntuk(0, d)}],\n          tombol: [tombolBuatLagi()]\n        });\n        hapusKirimanTertunda();\n        return;\n      }\n\n      // Ditolak sebelum menyentuh data (peran/validasi) \\u2014 tak ada yang tertulis.\n      strukTampil({\n        judul: '\\u274c WO tidak dibuat',\n        sub: (r.error && r.error.message) || 'Alasan tidak diketahui.',\n        items: [],\n        note: 'Tidak ada WO yang tersimpan. Perbaiki lalu kirim lagi.',\n        noteBuruk: true,\n        tombol: [{teks: 'Tutup', gaya: 'ghost', aksi: strukTutup}]\n      });\n      hapusKirimanTertunda();\n    }\n\n    function tampilkanPutus(err) {\n      // Kegagalan TRANSPOR, bukan jawaban server. Inilah 502 pada 12 Agu \\u2014 dan\n      // \"gagal\" adalah kesimpulan yang keliru: WO-nya bisa saja sudah masuk semua.\n      strukTampil({\n        judul: '\\u26a0\\ufe0f Sambungan putus \\u2014 belum tentu gagal',\n        sub: (err && err.message ? err.message : String(err || 'NetworkError')),\n        items: [],\n        note: 'Jawaban server tidak sampai ke layar, jadi WO Anda BISA JADI sudah masuk. ' +\n              'Tekan tombol di bawah \\u2014 kalau ternyata belum masuk, WO-nya dibuat sekarang juga. ' +\n              'Jangan mengisi formulir baru.',\n        tombol: [tombolCekLagi('Cek status / kirim ulang')]\n      });\n    }\n\n    // \\u2500\\u2500 kiriman tertunda dari sesi sebelumnya (halaman sempat ditutup/refresh) \\u2500\\u2500\n    function cekKirimanTertunda() {\n      var id = null;\n      try { id = localStorage.getItem(KIRIMAN_KEY); } catch (e) { return; }\n      if (!id) return;\n      _kirimanId = id;\n      document.getElementById('crBanner').classList.add('show');\n    }\n\n    function jalankanCekTertunda() {\n      showCreateLoading();\n      google.script.run\n        .withSuccessHandler(function(r) {\n          hideCreateLoading();\n          r = r || {};\n          if (r.kiriman === 'TIDAK_ADA') {\n            strukTampil({\n              judul: '\\u2705 Kiriman itu tidak pernah sampai',\n              sub: 'Tidak ada WO yang dibuat dari kiriman terakhir.',\n              items: [],\n              note: 'Aman diisi ulang dari awal.',\n              tombol: [{teks: 'Mengerti', gaya: 'primary', aksi: strukTutup}]\n            });\n            document.getElementById('crBanner').classList.remove('show');\n            hapusKirimanTertunda();\n            return;\n          }\n          // Sisa keadaannya identik dengan jawaban kirim biasa \\u2014 satu penafsir saja,\n          // supaya kalimat yang dibaca pemakai tak pernah berbeda antara dua jalan.\n          tanggapiKiriman(r);\n          if (r.kiriman !== 'SEDANG') document.getElementById('crBanner').classList.remove('show');\n        })\n        .withFailureHandler(function(err) {\n          hideCreateLoading();\n          strukTampil({\n            judul: '\\u26a0\\ufe0f Gagal memeriksa',\n            sub: (err && err.message) ? err.message : String(err || ''),\n            items: [], note: 'Coba lagi sebentar. Jangan mengisi formulir baru sebelum status jelas.',\n            tombol: [{teks: 'Coba lagi', gaya: 'primary', aksi: function() { strukTutup(); jalankanCekTertunda(); }}]\n          });\n        })\n        .handleCekKiriman({ kiriman_id: _kirimanId, token: PAGE_TOKEN });\n    }\n\n    function showNotification(message, type) {\n      var n = document.createElement('div');\n      n.className = 'notification notification-' + type + ' ' + type;\n      n.textContent = message;\n      document.body.appendChild(n);\n      setTimeout(function() { n.classList.add('show'); }, 100);\n      setTimeout(function() {\n        n.classList.remove('show');\n        setTimeout(function() { if (n.parentNode) document.body.removeChild(n); }, 300);\n      }, 3000);\n    }\n\n    function showCreateLoading(){ document.getElementById('crLoading').classList.add('show'); }\n    function hideCreateLoading(){ document.getElementById('crLoading').classList.remove('show'); }\n    function showCreateSuccess(msg){ document.getElementById('crSuccessMsg').textContent = msg || 'Work order berhasil dibuat!'; document.getElementById('crSuccess').classList.add('show'); }\n    // crBackToCreate DIHAPUS — overlay sukses kini <a target=\"_top\"> (native nav, aman sandbox).\n\n    // ----- init -----\n    window.addEventListener('DOMContentLoaded', function() {\n      var params = new URLSearchParams(window.location.search);\n      var successMsg = params.get('success');\n      if (successMsg) { showNotification(decodeURIComponent(successMsg), 'success'); }\n      addBlock(); // start with one block\n\n      document.getElementById('crBannerCek').onclick = jalankanCekTertunda;\n      document.getElementById('crBannerTutup').onclick = function() {\n        document.getElementById('crBanner').classList.remove('show');\n        hapusKirimanTertunda();\n      };\n      cekKirimanTertunda();\n    });\n  </script>\n</body>\n</html>";
